interface IAccessControlMock {
    function checkAccess(bytes4 _selector, address _contract, address _caller) external view returns (bool);
}

contract InvMutTest is Test {
    C c;
    address admin = address(0xA11CE);

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 kink, uint256 slope0, uint256 slope1) public {
        vm.assume(actor != address(0));
        // admissible SlopeData domain: 0 < kink < 1e27
        kink = bound(kink, 1, 1e27 - 1);

        AccessControlMock acm = new AccessControlMock();
        acm.grant(c.setSlopes.selector, address(c), actor);
        c.initialize(address(acm));

        vm.prank(actor);
        bool ok;
        try c.setSlopes(address(0xBEEF), C.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
