contract AccessControlMock is IAccessControlMock {
    mapping(bytes32 => bool) private allowed;

    function grant(bytes4 selector, address contractAddr, address caller) external {
        allowed[keccak256(abi.encodePacked(selector, contractAddr, caller))] = true;
    }

    function checkAccess(bytes4 _selector, address _contract, address _caller) external view returns (bool) {
        return allowed[keccak256(abi.encodePacked(_selector, _contract, _caller))];
    }
}

