pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        vm.assume(caller != address(0) && asset != address(0));
        // admissible SlopeData domain enforced by C.setSlopes itself: 0 < kink < 1e27
        kink = bound(kink, 1, 1e27 - 1);

        // adversarial counterparty: a live access-control contract that GRANTS access to the fuzzed caller
        GrantingAccessControl ac = new GrantingAccessControl();
        ac.grant(c.setSlopes.selector, address(c), caller);

        // drive c through `initialize` with the access control
        c.initialize(address(ac));

        // the granted caller performs an access-checked call with fuzzed valid slopes
        vm.prank(caller);
        bool ok;
        try c.setSlopes(asset, C.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "access-checked setSlopes by a granted caller must succeed after initialize");
    }
}

contract GrantingAccessControl {
    mapping(bytes4 => mapping(address => mapping(address => bool))) public allowed;

    function grant(bytes4 selector, address where, address who) external {
        allowed[selector][where][who] = true;
    }

    function checkAccess(bytes4 selector, address where, address caller) external view returns (bool) {
        return allowed[selector][where][caller];
    }

    function initialize(address) external {}
    function grantAccess(bytes4, address, address) external {}
    function revokeAccess(bytes4, address, address) external {}
    function role(bytes4, address) external pure returns (bytes32) {
        return bytes32(0);
    }
}

