import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(
        address caller,
        uint256 maxMultiplier,
        uint256 minMultiplier,
        uint256 rate
    ) public {
        MockAccessControl ac = new MockAccessControl();
        vm.assume(caller != address(0));

        // drive c through `initialize` with the access control contract
        bool initOk;
        try c.initialize(address(ac)) {
            initOk = true;
        } catch {
            initOk = false;
        }
        assertTrue(initOk);

        // grant this caller access to setLimits on c via the access control
        ac.grantAccess(c.setLimits.selector, address(c), caller);

        // rule: any caller granted access can successfully call the access-protected setLimits
        vm.prank(caller);
        bool ok;
        try c.setLimits(maxMultiplier, minMultiplier, rate) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

