pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Proxy p;
    AccessMock ac;

    function setUp() public {
        c = new C();
        ac = new AccessMock();
        p = new Proxy(address(c));
    }

    function testFuzz_property(address caller, uint256 maxMul, uint256 minMul, uint256 rate) public {
        vm.assume(caller != address(0));
        // initialize the proxied C with the supplied access control contract
        p.callInit(address(ac));
        bool ok;
        vm.prank(caller);
        try C(address(p)).setLimits(maxMul, minMul, rate) {
            ok = true;
        } catch {
            ok = false;
        }
        // AccessMock grants everyone access, so the access-controlled call must succeed
        assertTrue(ok);
    }
}

contract Proxy {
    address public immutable impl;

    constructor(address _impl) {
        impl = _impl;
    }

    function callInit(address ac) external {
        (bool ok, ) = impl.delegatecall(abi.encodeWithSelector(C.initialize.selector, ac));
        require(ok, "init failed");
    }

    fallback() external payable {
        (bool ok, bytes memory ret) = impl.delegatecall(msg.data);
        if (!ok) {
            assembly {
                revert(add(ret, 32), mload(ret))
            }
        }
        assembly {
            return(add(ret, 32), mload(ret))
        }
    }
}

contract AccessMock {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

